 async function refresh(){
  if(bootstrapRequest.current)return bootstrapRequest.current;
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);
  const request=api<Bootstrap>(admin?"/api/bootstrap?scope=ops":"/api/bootstrap",{signal:controller.signal}).then(data=>{
   setBoot(data);setAuth(false);
   if(!settingsReady.current){settingsReady.current=true;setUseModel(data.settings.modelConnected);setModelName(data.settings.model);setMethodNote(data.settings.methodNote);}
   return data;
  }).finally(()=>{clearTimeout(timer);bootstrapRequest.current=null;});
  bootstrapRequest.current=request;return request;
 }
