 async function submit(submission:ReadingSubmission={title,company,rawText:raw,sourceUrl:url,useModel},retryReadingId?:string){
  if(busy)return;if(submission.rawText.trim().length<40){setNotice(t("请粘贴至少40字的完整岗位描述。","Paste a job description of at least 40 characters."));return;}
  const controller=new AbortController();generationController.current=controller;setGenerationError("");
  const started=Date.now();setGenerationStarted(started);setGenerationStage("sending");setGenerating(true);setBusy(true);trackUsage("analyze_click",{view:"analyze"});
  try{
   const d=await requestAnalysis(submission,setGenerationStage,controller.signal);
   if(controller.signal.aborted)throw new DOMException("Aborted","AbortError");setGenerationStage("saving");try{localStorage.removeItem("wlo-input-draft-v1")}catch{}let stored=true;if(!admin)stored=await rememberReading(d.analysis);
   setPreview(d.analysis);if(!d.ephemeral)void refresh().then(data=>{if(data.analyses.some(a=>a.id===d.analysis.id&&a.revision>=d.analysis.revision))setPreview(current=>current?.id===d.analysis.id?null:current)}).catch(()=>{});choose(d.analysis);if(!d.modelError&&!d.reused)recordAnalysisTiming(Date.now()-started,submission.useModel);
   if(d.modelError){const reason=modelFailureText(d.modelFailure);setReadingFailures(old=>({...old,[d.analysis.id]:reason}));setNotice(reason[lang]+" "+t("当前展示证据草稿。","An evidence draft is shown. ")+(admin?t("已保存到工作区。","Saved to the workspace."):stored?t("已保存到本机，可点击“重新生成模型分析”。","Saved in this browser. Select Retry model analysis."):t("本机保存失败，请先下载当前结果。","Browser storage failed. Download the current result first.")));}
   else if(d.reused)setNotice(t("已打开同一文本的已有结果。","Opened the existing result for this text."));
   else if(stored&&!admin)setNotice(t("分析已完成，已保存到“我的分析”。","Reading complete. Saved to My readings in this browser."));
  }catch(e){
   const cancelled=controller.signal.aborted;let draftSaved=false;
   if(!admin&&!retryReadingId){const date=new Date().toISOString();draftSaved=await rememberReading({id:`draft-${crypto.randomUUID()}`,title:submission.title||t("未完成的分析","Unfinished reading"),company:submission.company,raw_text:submission.rawText,source_url:submission.sourceUrl,text_hash:"",engine:"rules",status:"draft",revision:1,created_at:date,updated_at:date,result:{headline:{zh:"分析尚未完成",en:"Analysis unfinished"},role:{zh:"已保留原文，可以修改后重新分析。",en:"The original text is saved. Edit it or try the analysis again."},terms:[],sociology:{zh:"",en:""},questions:[],conditions:[],gaps:[],comparisons:[]}});}
   if(cancelled){setNotice(draftSaved?t("已取消等待，输入已保存为本机草稿。","Waiting cancelled. Your input is saved as a local draft."):t("已取消等待，输入仍在当前页面。","Waiting cancelled. Your input remains on this page."));return;}
   const original=(e as Error).message,network=/fetch failed|failed to fetch|network\s*error|load failed|analysis_connection|analysis_stream_invalid|connection ended|connection unavailable/i.test(original);const message=network?modelFailureText("analysis_connection_error"):/^analysis_/.test(original)?modelFailureText(original):{zh:localizeError(original,"zh"),en:localizeError(original,"en")};if(retryReadingId)setReadingFailures(old=>({...old,[retryReadingId]:message}));setGenerationError(message[lang]);setNotice(message[lang]);}finally{generationController.current=null;setGenerating(false);setBusy(false);}
 }

